-- install: generated by `npm run guide:content` from content/guide/install.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 13,
  "outcome": "Claude Code установлен, вы вошли в аккаунт и провели первый разговор с агентом в своём репозитории.",
  "blocks": [
    {
      "type": "scene",
      "text": "Понедельник, первый день с агентом. Коллега ставит Claude Code через `sudo npm install -g`, запускает его в домашней папке и просит переписать модуль оплаты. К обеду у него ошибки прав, агент не видит проекта, а в diff — сорок файлов. Каждую из этих проблем снимает правильный первый запуск."
    },
    {
      "type": "text",
      "text": "Claude Code — агент в терминале. Он работает в папке, где вы его запустили: читает код, запускает команды и правит файлы. Ставится за минуту, и первый день лучше потратить не на правки, а на знакомство."
    },
    {
      "type": "bridge",
      "text": "Первый день в новой команде вы не правите продакшен. Вы ставите окружение по инструкции, открываете проект и задаёте вопросы тем, кто его знает. С агентом так же: сначала знакомство, потом правки."
    },
    {
      "type": "why",
      "text": "Агент видит проект через папку, в которой его запустили: оттуда он ищет и читает файлы, оттуда подхватывает CLAUDE.md. Запущенный в домашней папке, он не знает, о каком коде речь, и отвечает общими словами."
    },
    {
      "type": "heading",
      "text": "Установка"
    },
    {
      "type": "text",
      "text": "Рекомендуемый способ — официальный установщик: он ставит Claude Code и дальше обновляет его сам."
    },
    {
      "type": "command",
      "code": "curl -fsSL https://claude.ai/install.sh | bash",
      "caption": "macOS, Linux и WSL. В Windows PowerShell: `irm https://claude.ai/install.ps1 | iex`."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Без sudo",
      "text": "Через npm тоже можно, если стоит Node.js 22 или новее: `npm install -g @anthropic-ai/claude-code`. Но не добавляйте `sudo`: установка под root приводит к проблемам с правами и открывает риски безопасности. Homebrew и WinGet тоже подходят, но сами обновляются, только если задать переменную `CLAUDE_CODE_PACKAGE_MANAGER_AUTO_UPDATE=1`."
    },
    {
      "type": "heading",
      "text": "Первый запуск"
    },
    {
      "type": "text",
      "text": "Перейдите в корень проекта и наберите `claude`. В первый раз откроется браузер для входа: подойдёт подписка Claude Pro или Max, аккаунт Team или Enterprise (вход аккаунтом claude.ai по приглашению администратора) или аккаунт Claude Console с оплатой API. Дальше вход запоминается. Бесплатный план Claude Code не включает. Если компания работает через облако, Claude Code подключают и к нему: Amazon Bedrock, Agent Platform в Google Cloud, Microsoft Foundry."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик запускает Claude Code в корне своего проекта и спрашивает, что это за проект и как его запустить. Агент сам читает package.json, README и docker-compose, описывает стек и команды запуска и ничего не меняет.",
      "lines": [
        {
          "kind": "command",
          "text": "cd ~/projects/shop && claude",
          "typed": true
        },
        {
          "kind": "meta",
          "text": "Claude Code · вход выполнен"
        },
        {
          "kind": "prompt",
          "text": "Что это за проект и как запустить его локально?",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Читаю package.json, README.md, docker-compose.yml"
        },
        {
          "kind": "info",
          "text": "Node 22, PostgreSQL в Docker, фронтенд на Vite"
        },
        {
          "kind": "info",
          "text": "Запуск: docker compose up -d, затем npm run dev"
        },
        {
          "kind": "prompt",
          "text": "Где лежат тесты и чем их запускать?",
          "typed": true
        },
        {
          "kind": "info",
          "text": "tests/ — Vitest, команда npm test; e2e — npm run e2e"
        },
        {
          "kind": "done",
          "text": "Файлы не менялись: только чтение."
        }
      ]
    },
    {
      "type": "heading",
      "text": "Пять команд первого дня"
    },
    {
      "type": "list",
      "items": [
        "`claude -c` продолжает последний разговор в этой папке, `claude -r` открывает список прошлых.",
        "`/help` показывает все команды; `/` и Tab подсказывают их по мере ввода.",
        "`/init` создаёт черновик CLAUDE.md — памяти проекта. Подробно о нём — в шаге 2.2.",
        "`claude doctor` проверяет установку и настройки, если что-то пошло не так.",
        "`/exit` или дважды Ctrl+D — выход."
      ]
    },
    {
      "type": "spot",
      "title": "План первого дня · коллега",
      "prompt": "Коллега расписал свой первый день с Claude Code. Какой пункт вы бы вычеркнули?",
      "items": [
        {
          "id": "native",
          "text": "Поставить Claude Code официальным установщиком, без `sudo`."
        },
        {
          "id": "root",
          "text": "Запустить `claude` в корне рабочего проекта и войти."
        },
        {
          "id": "refactor",
          "text": "Сразу поручить агенту переписать модуль оплаты целиком."
        },
        {
          "id": "questions",
          "text": "Задать три вопроса, ответы на которые знает сам."
        }
      ],
      "answer": "refactor",
      "reveal": "Первый день — знакомство. Пока вы не видели, как агент читает ваш проект и как правит код, большая правка — прыжок вслепую. Начните с вопросов, ответы на которые знаете сами: они покажут, где агенту можно доверять, а где его стоит проверять."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Сначала вопросы, потом правки",
      "text": "Спросите агента о том, что знаете сами: как запустить проект, где главная логика, как устроены тесты. Так вы быстро поймёте, насколько ему можно доверять. Подробно — в шаге 1.3."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Установка: официальный установщик, npm и обновления",
          "url": "https://code.claude.com/docs/en/setup"
        },
        {
          "title": "Вход: подписки, Console и облачные провайдеры",
          "url": "https://code.claude.com/docs/en/authentication"
        },
        {
          "title": "Быстрый старт: первая сессия в проекте",
          "url": "https://code.claude.com/docs/en/quickstart"
        }
      ]
    }
  ],
  "practice": {
    "task": "Установите Claude Code, войдите и запустите его в корне рабочего проекта. Задайте три вопроса, ответы на которые знаете сами: как запустить проект, где живёт главная бизнес-логика, как устроены тесты.",
    "done": [
      "`claude --version` печатает версию;",
      "агент ответил на три вопроса, и вы сверили ответы с тем, что знаете;",
      "в проекте не изменился ни один файл."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  },
  "check": {
    "questions": [
      {
        "id": "sudo-install",
        "prompt": "Коллега ставит Claude Code командой `sudo npm install -g @anthropic-ai/claude-code`: без sudo «не хватает прав». Что посоветуете?",
        "options": [
          {
            "id": "native",
            "text": "Поставить официальным установщиком без sudo — он ещё и обновляется сам."
          },
          {
            "id": "sudo-ok",
            "text": "Оставить sudo: для глобальных пакетов npm это обычное дело, раз иначе не хватает прав."
          },
          {
            "id": "docker",
            "text": "Запускать Claude Code в Docker-контейнере, чтобы вообще не трогать права на машине."
          }
        ]
      },
      {
        "id": "where-run",
        "prompt": "Вы открыли терминал в домашней папке, запустили `claude` и спросили, как запустить тесты проекта shop. Агент отвечает общими словами. В чём дело?",
        "options": [
          {
            "id": "wrong-folder",
            "text": "Он запущен не там: агент видит папку запуска, а не shop. Запустите `claude` в корне проекта."
          },
          {
            "id": "no-claude-md",
            "text": "В проекте нет CLAUDE.md, а без него агент не знает, где лежат тесты и как их запускать."
          },
          {
            "id": "no-init",
            "text": "Не выполнен `/init`: пока его не запустить, агент не читает файлы этого проекта самостоятельно."
          }
        ]
      },
      {
        "id": "continue",
        "prompt": "Вчера вы долго обсуждали с агентом задачу и закрыли терминал. Как продолжить с того же места?",
        "options": [
          {
            "id": "continue",
            "text": "`claude -c` в той же папке: разговор продолжится целиком."
          },
          {
            "id": "retell",
            "text": "Запустить `claude` и пересказать вчерашний разговор с решениями."
          },
          {
            "id": "lost",
            "text": "Никак: история пропадает вместе с терминалом."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'install';
insert into private.guide_checks (step_id, key) values ('install', $json${
  "sudo-install": {
    "correct": [
      "native"
    ],
    "why": {
      "native": "Да. `sudo npm install -g` — источник проблем с правами и рисков безопасности, а нативный установщик решает и вопрос прав, и обновления.",
      "sudo-ok": "Именно так делать не стоит: глобальная установка под root ведёт к проблемам с правами и рискам безопасности.",
      "docker": "Обходной путь ценой лишней настройки: проект придётся монтировать в контейнер. Официальный установщик решает вопрос прав без root."
    }
  },
  "where-run": {
    "correct": [
      "wrong-folder"
    ],
    "why": {
      "wrong-folder": "Да. Агент работает в папке запуска и её подпапках: из корня проекта он видит код, настройки и тесты.",
      "no-claude-md": "CLAUDE.md помогает, но файлы проекта агент читает и без него. Здесь он просто не видит проект из домашней папки.",
      "no-init": "`/init` лишь создаёт черновик CLAUDE.md. Читать проект агент может и без него — если запущен в его папке."
    }
  },
  "continue": {
    "correct": [
      "continue"
    ],
    "why": {
      "continue": "Да. `-c` продолжает последний разговор в текущей папке, а `claude -r` и `/resume` позволяют выбрать любой из прошлых.",
      "retell": "Можно, но пересказ теряет детали. Разговоры сохраняются: `-c` вернёт вчерашний целиком.",
      "lost": "Не пропадает: сессии сохраняются, их открывают `claude -c`, `claude -r` или `/resume` внутри сессии."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

