-- conventions: generated by `npm run guide:content` from content/guide/conventions.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 15,
  "outcome": "Вы записываете в CLAUDE.md то, что агент не может угадать, — команды, соглашения, подвохи — и знаете, где совета мало и нужен запрет.",
  "blocks": [
    {
      "type": "scene",
      "text": "В CLAUDE.md проекта заглавными написано: «НИКОГДА не правь старые миграции». В пятницу агент чинил упавший деплой и поправил старую миграцию — так было быстрее. Правило он прочитал. Но это был совет."
    },
    {
      "type": "text",
      "text": "Хороший CLAUDE.md отвечает на вопросы, которые агент не решит, прочитав код: какой командой проверять, о чём договорилась команда, где лежат грабли. Остальное он увидит сам."
    },
    {
      "type": "bridge",
      "text": "Вы различаете соглашение в README и проверку в CI: первое просит, вторая не пропустит. CLAUDE.md — README для агента, а то, что нельзя нарушать, живёт в настройках."
    },
    {
      "type": "why",
      "text": "CLAUDE.md — текст в окне, а не код Claude Code. Агент взвешивает его вместе со всем остальным: задачей, ошибками, собственными выводами, и иногда другое перевешивает. Правила разрешений Claude Code проверяет сам, до того как действие выполнится, поэтому их нельзя «перевесить»."
    },
    {
      "type": "compare",
      "before": {
